var i=`0993-oyster-omelette`;var n=`world-0993`;var a=`TW`;var s=`east-asia`;var o=4;var r=32;var l={en:`Oyster Omelette`,ua:`Омлет з устрицями`};var g={en:`Oyster Omelette is a Taiwan dish made with oyster, chicken egg, tapioca starch, bean sprouts. This home-scale recipe assigns measured ingredients to the steps where they are used. Tapioca starch replaces sweet-potato starch; the omelet has a slightly different texture.`,ua:`Омлет з устрицями, страва кухні країни Тайвань. Основні складники: устриця, куряче яйце, тапіоковий крохмаль, проростки квасолі. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів. Тапіоковий крохмаль замінює бататовий; текстура омлету буде дещо іншою.`};var c=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:10,i:[[`oyster`,390,`g`],[`chicken-egg`,4,`pcs`],[`tapioca-starch`,130,`g`],[`water`,240,`ml`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 14 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 14 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:14,i:[[`canola-oil`,65,`ml`],[`bean-sprouts`,180,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:5,i:[[`chili-garlic-sauce`,85,`g`],[`ketchup`,55,`g`],[`rice-vinegar`,25,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,20,`g`]]}];var h={slug:i,id:n,country:`TW`,region:s,servings:4,minutes:32,title:l,text:g,steps:c};export{a as country,h as default,n as id,r as minutes,s as region,o as servings,i as slug,c as steps,g as text,l as title};